import threading, collections

cv, q = threading.Condition(), collections.deque()

def take():
    with cv:                                # acquires the underlying lock
        cv.wait_for(lambda: len(q) > 0)     # while not pred(): cv.wait()
        return q.popleft()
def put(item):
    with cv:
        q.append(item)                      # change state first
        cv.notify()                         # then wake the wait set

